   Q('note', 'Golden Record includes greetings in __________ languages', ['55', 'fifty-five'], 'including greetings in fifty-five languages', 'There are 55 languages.', skill='numbers', max=1),
   Q('note', 'Voyager 2 entered interstellar space in __________', ['2018'], 'Voyager 1 in 2012 and Voyager 2 in 2018', 'Voyager 2 entered in 2018.', skill='numbers', trap='2012 is Voyager 1.', max=1),
